pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // 1. keep the fuzzed domain wide: any caller is admissible
        // 2. set the scenario: the current (zero) owner hands ownership to the fuzzed
        //    caller so that a call from that caller to owned() is admissible,
        //    then drive c through `owned` and observe the public owner getter
        vm.assume(caller != address(0));
        vm.prank(address(0));
        c.transferOwnership(caller);

        address ownerBefore = c.owner();
        vm.prank(caller);
        try c.owned() {
            // call succeeded; owner must be untouched by owned()
        } catch {
            // call reverted; owner must also be untouched
        }

        // 3. single universal assertion: owned() never changes the owner
        assertTrue(c.owner() == ownerBefore);
    }
}

