pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address thirdParty) public {
        vm.assume(newOwner != address(0));
        vm.assume(thirdParty != address(0));

        // owner is address(0) at deployment; have it hand ownership to the fuzzed address
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // the owner invokes owned(); in the reference this must not change the stored owner
        vm.prank(newOwner);
        c.owned();
        assertTrue(c.owner() == newOwner, "owned() must not change the stored owner");

        // ownership must still be transferable to an arbitrary third party afterwards
        vm.prank(newOwner);
        c.transferOwnership(thirdParty);
        assertTrue(c.owner() == thirdParty, "owner must remain intact after owned()");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Wide admissible domain: caller may be ANY address (including address(0),
        // which is the deploy-time owner of C, since the constructor leaves owner zero).
        // newOwner must be a usable target for transferOwnership.
        vm.assume(newOwner != address(0));

        // Put `caller` in control when possible: the current owner (initially
        // address(0)) transfers ownership to `caller`. This succeeds in the
        // reference for caller == address(0) and keeps the domain otherwise wide.
        vm.prank(c.owner());
        c.transferOwnership(caller);

        address ownerBefore = c.owner();

        // Drive the mutated entry point with the fuzzed caller.
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        // Observable follow-up: if owned() completed, ownership must be intact —
        // the stored owner is unchanged and the owner still exclusively holds the
        // right to transfer ownership to the fuzzed target.
        bool transferOk;
        if (ok) {
            vm.prank(caller);
            try c.transferOwnership(newOwner) { transferOk = true; } catch { transferOk = false; }
        }

        // General rule: owned() never changes the owner, and after it succeeds the
        // (unchanged) owner can still transfer ownership away. The mutant breaks
        // this for any admissible input where the caller of owned() differs from
        // the stored owner at the moment of the write (owner becomes msg.sender).
        assertTrue(!ok || (c.owner() == newOwner && transferOk && ownerBefore != address(0) ? c.owner() == newOwner && transferOk : c.owner() == ownerBefore && transferOk));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != newOwner);
        address currentOwner = c.owner();
        // current owner hands ownership to the fuzzed new owner
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);
        // the new owner exercises the entry point owned()
        vm.prank(newOwner);
        c.owned();
        // later, the (still-recorded) owner may transfer ownership onward to the fuzzed caller
        vm.prank(c.owner());
        c.transferOwnership(caller);
        // rule: the recorded owner is exactly the party ownership was last transferred to
        assertTrue(c.owner() == caller);
    }
}
